"""Discover WebDataset shards generated by local preprocessing."""

from pathlib import Path


def find_shards(data_dir, folder, dataset):
    """Return existing shards in filename order, allowing custom shard sizes."""
    pattern = dataset + '-' + '[0-9]' * 6 + '.tar'
    return [str(path) for path in sorted((Path(data_dir) / folder).glob(pattern))]
